sys_script_include.script:
var TrainingValidationUtils = Class.create();
TrainingValidationUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkCourseSchedule: function() {
        var encodedQuery = this.getParameter("sysparm_encodedQuery");
        var schedules = [];

        if (encodedQuery) {
            var scheduleRecord = new GlideRecord("x_1567520_shark_0_training_schedule");
            scheduleRecord.addEncodedQuery(encodedQuery); 
            scheduleRecord.query(); 

            while (scheduleRecord.next()) {
                schedules.push({
                    sys_id: scheduleRecord.sys_id.toString(),
                    courseName: scheduleRecord.course.name.toString()
                });
            }
        }
        return JSON.stringify(schedules);
    },

    type: 'TrainingValidationUtils' 
});
